<script setup lang="ts">
import type{ApiEnvelope,User}from'~/types/api'
definePageMeta({layout:'dashboard',middleware:'auth'});useSeoPage('Profile','Manage account details and password.','/dashboard/profile')
const{user}=useAuth();const profile=reactive({name:user.value?.name||'',email:user.value?.email||''});const password=reactive({current_password:'',password:'',password_confirmation:''});const error=ref('');const{request}=useApi();const{show}=useToast();const savingProfile=ref(false);const savingPassword=ref(false);const initials=computed(()=>user.value?.name?.split(/\s+/).map(v=>v[0]).slice(0,2).join('').toUpperCase()||'U')
async function saveProfile(){savingProfile.value=true;error.value='';try{const response=await request<ApiEnvelope<User>>('profile',{method:'PATCH',body:profile});user.value=response.data;show(response.message||'Profile updated.')}catch(e:any){error.value=Object.values(e?.data?.errors||{}).flat().join(' ')||e?.data?.message||'Unable to update profile.'}finally{savingProfile.value=false}}
async function savePassword(){savingPassword.value=true;error.value='';try{const response=await request<ApiEnvelope<null>>('profile/password',{method:'PUT',body:password});show(response.message||'Password updated.');Object.assign(password,{current_password:'',password:'',password_confirmation:''})}catch(e:any){error.value=Object.values(e?.data?.errors||{}).flat().join(' ')||e?.data?.message||'Unable to update password.'}finally{savingPassword.value=false}}
</script>
<template><div class="dashboard-page max-w-[760px]"><h1 class="page-title">Profile</h1><p class="mt-1 text-sm text-text-secondary">Manage your identity and account password.</p><p v-if="error" class="mt-5 rounded-lg border border-danger-border bg-danger-bg p-4 text-sm text-danger" role="alert">{{ error }}</p><section class="surface mt-6 overflow-hidden"><div class="flex items-center gap-4 border-b border-border p-6"><div class="grid size-14 shrink-0 place-items-center rounded-full border border-brand-mid bg-brand-light text-lg font-bold text-brand">{{ initials }}</div><div class="min-w-0"><h2 class="truncate text-base font-bold">{{ user?.name }}</h2><p class="truncate text-sm text-text-secondary">{{ user?.email }}</p><span class="mt-1.5" :class="user?.email_verified_at?'badge-success':'badge-warning'">{{ user?.email_verified_at?'Email verified':'Verification pending' }}</span></div></div><form class="grid gap-5 p-6" @submit.prevent="saveProfile"><h2 class="text-sm font-semibold">Personal information</h2><div><label class="label" for="profile-name">Full name</label><input id="profile-name" v-model="profile.name" class="input" required maxlength="120"></div><div><label class="label" for="profile-email">Email address</label><input id="profile-email" v-model="profile.email" class="input" type="email" required><p class="mt-1.5 text-xs text-text-muted">Changing the email address requires verification again.</p></div><div class="flex justify-end"><button class="btn-primary" :disabled="savingProfile">{{ savingProfile?'Saving…':'Save profile' }}</button></div></form></section><form class="surface mt-5 grid gap-5 p-6" @submit.prevent="savePassword"><div><h2 class="text-sm font-semibold">Change password</h2><p class="mt-1 text-xs text-text-muted">Updating your password revokes other API sessions.</p></div><div><label class="label" for="current-password">Current password</label><input id="current-password" v-model="password.current_password" class="input" type="password" autocomplete="current-password" required></div><div class="grid gap-5 sm:grid-cols-2"><div><label class="label" for="new-password">New password</label><input id="new-password" v-model="password.password" class="input" type="password" autocomplete="new-password" required></div><div><label class="label" for="confirm-password">Confirm password</label><input id="confirm-password" v-model="password.password_confirmation" class="input" type="password" autocomplete="new-password" required></div></div><p class="text-xs text-text-muted">Use at least 12 characters with uppercase, lowercase, a number, and a symbol.</p><div class="flex justify-end"><button class="btn-primary" :disabled="savingPassword">{{ savingPassword?'Updating…':'Update password' }}</button></div></form></div></template>
